import {metrics,score,pct,overdue,actionQueue,brief,closeFinding,validate} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=await fetch('data.json').then(r=>{if(!r.ok)throw Error('Dataset unavailable');return r.json()});validate(seed);
let d=structuredClone(seed),audit=[],generated=null,briefApproval=null,view='overview',queueFilter='all',calendarMonth='2026-10';
const nav=[['overview','◈','Senior oversight'],['monitoring','▦','Monitoring programme'],['outcomes','◉','Customer outcomes'],['regulatory','⌁','Regulatory change'],['governance','◇','Governance & SMF16'],['privacy','▣','Privacy oversight'],['fincrime','⛨','Financial crime'],['brief','≋','AI management brief'],['about','↗','About the project']];
const disclaimer='Portfolio prototype · All records and firm details are fictional. Not production compliance tooling, legal/regulatory advice or an actual SMF16 system.';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
function log(type,id,reviewer,note){audit.unshift({type,id,reviewer,note,time:new Date().toISOString()});briefApproval=null;generated=null;}
function badge(s){return `<span class="pill ${s==='High'?'High':s==='Medium'?'Medium':['Open','Pending','Interpretation pending','Review pending'].includes(s)?'pending':''}">${esc(s)}</span>`}
function due(x){return `${esc(x.due)} ${overdue(x,d.meta.asOf)?'<span class="pill overdue">Overdue</span>':''}`}
function notice(text=disclaimer){return `<div class="notice">${text}</div>`}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<small>${sub}</small>`:''}</div>${action}</div>${body}</section>`}
function stat(label,value,detail,cls=''){return `<div class="stat"><div class="stat-top">${label}<span>↗</span></div><strong class="${cls}">${value}</strong><small>${detail}</small></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">No matching records.</td></tr>`}</tbody></table></div>`}
function reviewButton(x,label='Review'){return `<button data-detail="${x.id}">${label} ↗</button>`}
function map(){let cells='';for(let l=5;l>=1;l--)for(let i=1;i<=5;i++){const n=l*i;const rs=d.risks.filter(r=>r.likelihood===l&&r.impact===i);cells+=`<div class="matrix-cell ${n>=20?'critical':n>=12?'hot':n>=6?'mid':''}" title="Likelihood ${l}, impact ${i}">${rs.map(r=>`<button class="risk-pin" data-risk="${r.id}" aria-label="Explore ${esc(r.name)}, score ${score(r)}">${r.id}</button>`).join('')}</div>`}return `<div class="risk-map"><div class="y-label">LIKELIHOOD →</div><div class="matrix" role="group" aria-label="Risk map: likelihood by impact">${cells}</div></div><div class="map-axis"><span>1 · LOW</span><span>IMPACT →</span><span>5 · HIGH</span></div><div class="legend"><span><i style="background:#eff3e9"></i>1–5 Low</span><span><i style="background:#f3ecd9"></i>6–11 Moderate</span><span><i style="background:#eed8cc"></i>12–19 High</span><span><i style="background:#dfb3a5"></i>20–25 Critical</span></div>`}
function queueItems(xs){return xs.map(x=>`<div class="queue-item"><span class="queue-index">${x.id}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.owner)} · ${esc(x.module||'Monitoring')}</p>${due(x)}</div>${reviewButton(x,'Open')}</div>`).join('')||'<div class="empty">No items in this queue.</div>'}
function timeline(){const groups=calendarMonth==='2026-10'?[['05–11 OCT','2026-10-05','2026-10-11'],['12–18 OCT','2026-10-12','2026-10-18'],['19–25 OCT','2026-10-19','2026-10-25'],['26 OCT–01 NOV','2026-10-26','2026-11-01']]:[['02–08 NOV','2026-11-02','2026-11-08'],['09–15 NOV','2026-11-09','2026-11-15'],['16–22 NOV','2026-11-16','2026-11-22'],['23–29 NOV','2026-11-23','2026-11-29']];return `<div class="timeline">${groups.map(([label,start,end])=>`<div class="week"><div class="week-label">${label}</div>${d.monitoring.filter(m=>m.start<=end&&m.end>=start).map(m=>`<button class="event ${m.status==='Planned'?'planned':''}" data-monitor="${m.id}">${esc(m.name)}<small>${m.id} · ${m.status} · ${m.start.slice(8)}–${m.end.slice(8)}</small></button>`).join('')||'<span class="muted">No reviews scheduled</span>'}</div>`).join('')}</div>`}
function overview(){const m=metrics(d),p=metrics(d,d.meta.previousAsOf);return heading('A clear line of sight','Compliance control room','From operational evidence to informed senior oversight.',`<button class="primary" data-prepare>Prepare SMF16 monthly briefing ↗</button>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">OVERSIGHT SNAPSHOT / OCTOBER 2026</div><h2>See the risk.<br>Understand the evidence.<br>Make the next decision.</h2><p>A governed view of monitoring, customer outcomes and actions — with human judgement at every material decision.</p><div class="hero-bottom"><span><span class="green-dot"></span>DETERMINISTIC METRICS</span><span>HUMAN REVIEW REQUIRED</span><a href="#about">Explore the project ↗</a></div></div><div class="hero-signal"><div class="signal-top"><span>CUSTOMER OUTCOME SIGNAL</span><span>SAMPLED QA</span></div><div class="signal-value">${m.qa}% <small>pass rate</small></div><div class="signal-bars">${d.outcomes.filter(o=>o.month==='2026-09').concat(d.outcomes.filter(o=>o.month==='2026-10')).map(o=>`<span style="height:${pct(o.qaPassed,o.qaTested)}%" title="${o.month} ${o.journey}: ${pct(o.qaPassed,o.qaTested)}%"></span>`).join('')}</div><p>${m.qaPassed} of ${m.qaTested} tests passed · prior period ${p.qa}%<br>Sample signal requires investigation, not an automated conclusion.</p></div></section>`+notice()+`<div class="stats">${stat('Open monitoring findings',m.open,`${m.high} high severity · ${p.open} at 30 Sep`)}${stat('Overdue monitoring actions',m.overdue,`${m.allOverdue} overdue across the full queue`,'red')}${stat('Vulnerable customer outcomes',m.vulnerable+'%',`${m.vulnerableGood}/${m.vulnerableTested} good · prior ${p.vulnerable}%`,'amber')}${stat('Awaiting evidence review',m.awaitingEvidenceReview,'Independent challenge before closure','teal')}</div><div class="grid">${panel('Compliance risk landscape','Select a risk to trace business area → control → finding.',map(),'<a href="#governance">Risk register ↗</a>')}${panel('Needs attention now','Overdue items across monitoring, privacy and governance.',queueItems(actionQueue(d).filter(x=>overdue(x,d.meta.asOf)).slice(0,4)),'<a href="#governance">Full action queue ↗</a>')}</div><div class="grid">${panel('What changed?','Compared with the 30 September synthetic snapshot.',`<div class="panel-body"><h3>Monitoring findings: ${p.open} → ${m.open}</h3><p class="muted">New findings and completed closures are derived from recorded opening and closure dates.</p><h3>Complaints in sample: ${p.complaints} → ${m.complaints}</h3><p class="muted">Customer support and complaint taxonomy are the leading review themes. Sample populations may differ.</p><a class="help-link" href="#outcomes">Inspect customer outcome evidence ↗</a></div>`)}${panel('Closure evidence spotlight','F04 · Personal data handling',`<div class="panel-body"><span class="pill Medium">Evidence submitted</span><h3 style="margin-top:12px">Retention exception log awaiting validation</h3><p class="muted">A reconciliation has been submitted. Independent retest and scope assessment remain outstanding.</p>${reviewButton(d.findings.find(f=>f.id==='F04'),'Review closure evidence')}</div>`)}</div>${panel('Monitoring horizon','Thematic reviews and independent retests.',timeline(),'<a href="#monitoring">Open programme ↗</a>')}`}
function monitoring(){return heading('Assurance / control testing','Compliance monitoring programme','Plan reviews, test controls and trace findings through to evidenced closure.')+notice()+`<div class="toolbar"><label>View <select id="monitor-mode"><option value="all">All findings</option><option value="overdue">Overdue only</option><option value="evidence">Evidence submitted</option><option value="closed">Closed</option></select></label><input id="finding-search" aria-label="Search findings" placeholder="Search finding, owner or control…"><span class="muted">8 findings · 6 controls · 8 planned/completed reviews</span></div><div id="findings-table" class="panel section"></div>${panel('Interactive monitoring calendar','Select a review to inspect its scope, control and findings.',`<div id="calendar">${timeline()}</div>`,`<select id="calendar-month" aria-label="Calendar month"><option value="2026-10" ${calendarMonth==='2026-10'?'selected':''}>October 2026</option><option value="2026-11" ${calendarMonth==='2026-11'?'selected':''}>November 2026</option></select>`)}<div class="section"></div>${panel('Control test results','Synthetic October tests. A test exception is not automatically a breach.',table(['Control / risk','Tests','Exceptions','Pass rate'],d.controls.map(c=>[`${c.id} · ${esc(c.name)}<small>${c.riskId} · ${c.date}</small>`,c.tested,c.failed,`${pct(c.tested-c.failed,c.tested)}%`])))}`}
function renderFindings(){const q=($('#finding-search')?.value||'').toLowerCase(),mode=$('#monitor-mode')?.value||'all';const rows=d.findings.filter(f=>(f.id+' '+f.title+' '+f.owner+' '+f.controlId).toLowerCase().includes(q)).filter(f=>mode==='all'||mode==='overdue'&&overdue(f,d.meta.asOf)||mode==='evidence'&&f.status==='Evidence submitted'||mode==='closed'&&f.status==='Closed');$('#findings-table').innerHTML=table(['Finding / control','Severity','Owner / due','Status','Evidence'],rows.map(f=>[`${f.id} · <strong>${esc(f.title)}</strong><small>${f.controlId} · ${esc(f.action)}</small>`,badge(f.severity),`${esc(f.owner)}<small>${due(f)}</small>`,`${badge(f.status)}<small>${f.reviewed?'Human validated':'Validation pending'}</small>`,reviewButton(f,`${f.evidence.length} evidence item${f.evidence.length===1?'':'s'}`)]));}
function outcomes(){const m=metrics(d),p=metrics(d,d.meta.previousAsOf);return heading('Consumer Duty / customer journeys','Customer outcomes','Look beyond averages. Follow the customer journey, sample and root cause.')+notice('Fictional QA samples and aggregate complaints. Good-outcome criteria are illustrative. No real customer data or population-wide outcome assessment.')+`<div class="stats">${stat('QA sample pass rate',m.qa+'%',`${m.qaPassed}/${m.qaTested} · prior ${p.qa}%`)}${stat('Complaints in sample',m.complaints,`Prior period ${p.complaints}`,'amber')}${stat('Upheld complaints',m.upheld,`${pct(m.upheld,m.complaints)}% of sampled complaints`)}${stat('Vulnerable good outcomes',m.vulnerable+'%',`${m.vulnerableGood}/${m.vulnerableTested} · prior ${p.vulnerable}%`,'red')}</div><div class="outcome-cards section">${d.outcomes.filter(o=>o.month==='2026-10').map(o=>`<section class="panel"><div class="panel-head"><h2>${o.journey}</h2><span class="tag">${o.id}</span></div><div class="panel-body"><div class="muted">QA sample pass rate</div><div class="big">${pct(o.qaPassed,o.qaTested)}%</div><div class="metric-bar"><span style="width:${pct(o.qaPassed,o.qaTested)}%"></span></div><p class="muted" style="font-size:10px;margin-top:7px">${o.qaPassed} / ${o.qaTested} tests passed</p><div class="outcome-meta"><div><strong>${o.complaints}</strong>Complaints</div><div><strong>${o.upheld}</strong>Upheld</div><div><strong>${o.vulnerableGood}/${o.vulnerableTested}</strong>Vulnerable: good</div></div><h3>Root-cause theme</h3><p>${esc(o.rootCause)}</p><div class="callout">${esc(o.commentary)}</div></div></section>`).join('')}</div>${panel('Management commentary & response','Interpretation remains subject to review.',`<div class="panel-body"><p>Prioritise support hand-offs in lending, complaint taxonomy and independent vulnerability QA calibration. Investigate journey mix, severity and sample selection before treating the movements as causal evidence.</p><div class="split-actions"><button data-detail="F01">Support hand-off · F01 ↗</button><button data-detail="F02">Complaint root cause · F02 ↗</button><button data-detail="F07">QA calibration · F07 ↗</button></div></div>`)}<div class="section"></div>${panel('Period comparison & source data','Each percentage is computed from these counts.',table(['Record / period','Journey','QA passed / tested','Complaints / upheld','Vulnerable good / tested'],d.outcomes.map(o=>[`${o.id} · ${o.month}`,o.journey,`${o.qaPassed}/${o.qaTested}`,`${o.complaints}/${o.upheld}`,`${o.vulnerableGood}/${o.vulnerableTested}`])))}`}
function regulatory(){return heading('Horizon scanning / impact assessment','Regulatory change','A demonstration of change governance, from interpretation to implementation.')+notice('ALL REGULATORY CONTENT BELOW IS INVENTED. No live FCA/ICO feed, current regulatory research or legal interpretation is connected. Internal demo dates are not regulatory deadlines.')+panel('Change & impact register','Fictional training scenarios inspired by oversight workflows.',table(['Scenario / source','Affected products / impact','Owner / due','Review status','Action'],d.changes.map(c=>[`${c.id} · <strong>${esc(c.title)}</strong><small>${esc(c.source)} · ${c.published}</small>`,`${esc(c.products)}<small>${esc(c.impact)}</small>`,`${esc(c.owner)}<small>${due(c)}</small>`,badge(c.status),reviewButton(c,'Review interpretation')])))+`<div class="section"></div>${panel('Controlled change workflow','Human specialist interpretation precedes implementation.',`<div class="panel-body"><div class="flow">${[['01','Capture scenario','Source, date, accountable owner and impacted risk.'],['02','Assess impact','Map products, journeys, processes and control changes.'],['03','Human interpretation','Qualified reviewer validates scope and rationale.'],['04','Assign implementation','Named owner, internal target date and dependencies.'],['05','Validate evidence','Independent review of testing and implementation evidence.'],['06','Governance forum','Escalate gaps and record decisions. No automatic compliance conclusion.']].map(([n,t,s])=>`<div class="node"><b>${n}</b><strong>${t}</strong><small>${s}</small></div>`).join('')}</div></div>`)}`}
function governance(){const m=metrics(d);return heading('Senior oversight / reasonable-steps evidence','Governance & SMF16 oversight','What needs attention, who owns it, and what supports the decision?')+notice('Inspired by information a senior compliance function may need. Gurjit Kaila does not claim SMF16 status, Head of Compliance responsibility or formal second-line leadership experience. This is not a complete reasonable-steps framework.')+`<div class="stats">${stat('High-severity open findings',m.high,'Human validation and escalation required','red')}${stat('Full-queue overdue items',m.allOverdue,'Monitoring + specialist + governance','red')}${stat('Pending attestations',d.attestations.filter(a=>a.status!=='Attested').length,'Reviewer identity is illustrative')}${stat('Potential issues',d.issues.length,'Assessment pending; no breach conclusion')}</div><div class="grid">${panel('Compliance risk register','Illustrative residual scores: likelihood × impact.',table(['Theme / owner','Current / previous','Trace'],d.risks.map(r=>[`${r.id} · <strong>${esc(r.name)}</strong><small>${esc(r.owner)}</small>`,`${score(r)}/25 <small>Prior ${r.previousScore}/25</small>`,`<button data-risk="${r.id}">Trace evidence ↗</button>`])))}${panel('Attestations & issue assessment','Named human review, scope and rationale.',`<div class="panel-body">${d.attestations.map(a=>`<div class="audit"><h3>${a.id} · ${esc(a.title)}</h3><p>${esc(a.evidence)}</p><p>${due(a)} · ${badge(a.status)}</p>${reviewButton(a,'Review attestation')}</div>`).join('')}${d.issues.map(i=>`<div class="audit"><h3>${i.id} · ${esc(i.title)}</h3><p>${esc(i.classification)}</p>${reviewButton(i,'Review issue')}</div>`).join('')}</div>`)}</div><div class="toolbar"><h2>Accountable action queue</h2><select id="queue-filter" aria-label="Filter action queue"><option value="all">All open items</option><option value="overdue" ${queueFilter==='overdue'?'selected':''}>Overdue only</option><option value="Monitoring" ${queueFilter==='Monitoring'?'selected':''}>Monitoring</option><option value="Privacy" ${queueFilter==='Privacy'?'selected':''}>Privacy</option><option value="Financial crime" ${queueFilter==='Financial crime'?'selected':''}>Financial crime</option><option value="Regulatory change" ${queueFilter==='Regulatory change'?'selected':''}>Regulatory change</option><option value="Governance" ${queueFilter==='Governance'?'selected':''}>Governance</option></select></div><div class="panel section" id="action-table"></div>${panel('Decision & evidence trail','Session-only demo trail. No authentication, tamper protection or durable audit storage.',`<div class="panel-body audit-list">${audit.length?audit.map(a=>`<div class="audit"><strong>${esc(a.type)} · ${a.id}</strong><p>${esc(a.note)}</p><small>${esc(a.reviewer)} · ${a.time}</small></div>`).join(''):'<p class="muted">No decisions this session. Open F04 to inspect submitted evidence or review an attestation to demonstrate a recorded decision.</p>'}<p class="safety">Pre-seeded closures F06 and F08 contain fictional evidence and independent reviewer details in the monitoring register.</p></div>`,'<button id="export-audit">Export trail ↓</button>')}`}
function renderQueue(){let xs=actionQueue(d).filter(x=>queueFilter==='all'||queueFilter==='overdue'&&overdue(x,d.meta.asOf)||x.module===queueFilter);$('#action-table').innerHTML=table(['Item / action','Module','Owner','Due / status','Review'],xs.map(x=>[`${x.id} · <strong>${esc(x.title)}</strong><small>${esc(x.action||x.evidence)}</small>`,x.module,esc(x.owner),`${due(x)}<small>${badge(x.status)}</small>`,reviewButton(x)]));}
function specialist(type){const privacy=type==='privacy',xs=privacy?d.privacy:d.fincrime;return heading(privacy?'Data handling / specialist challenge':'Specialist risk / control exposure',privacy?'Data protection & privacy':'Financial crime oversight',privacy?'DPIA-style, access-request and incident oversight — a fictional workflow demonstration.':'High-level AML, fraud and sanctions control oversight — a fictional exposure module.')+notice(privacy?'All privacy records are fictional. No direct GDPR operational experience is claimed for Gurjit. This register does not determine legal deadlines, lawful basis, incident reportability or DPIA sufficiency. Specialist review is required.':'All financial-crime records are fictional. This demonstrates oversight exposure, not expert financial-crime advice, MLRO responsibility or AML/sanctions decision-making. Specialist judgement is required.')+panel(privacy?'Privacy risk & action register':'Financial crime risk & action register','Internal demo targets; all material assessments require human review.',table(['Record / type','Risk / required action','Owner / due','Status','Review'],xs.map(x=>[`${x.id} · <strong>${esc(x.title)}</strong><small>${esc(x.type)} · ${x.riskId}</small>`,`${esc(x.risk)}<small>${esc(x.action)}</small>`,`${esc(x.owner)}<small>${due(x)}</small>`,badge(x.status),reviewButton(x)])))+`<div class="section"></div>${panel('Escalation path','Capture facts → specialist assessment → human decision → governance.',`<div class="panel-body"><p class="muted">The prototype captures oversight questions and accountable actions. It does not perform customer screening, determine suspicious activity, process real access requests or decide whether an incident is reportable.</p><button data-risk="${privacy?'R04':'R05'}">Trace linked risk, control and findings ↗</button></div>`)}`}
function briefing(){return heading('Structured data / governed interpretation','AI management brief','The insight layer sits above calculated metrics. Every output remains a draft.',`<div class="split-actions"><button class="primary" data-prepare>Prepare SMF16 monthly briefing</button>${generated?'<button id="download-brief">Download briefing ↓</button><button id="print-brief">Print / PDF</button>':''}</div>`)+notice('V1 uses deterministic briefing logic, not a live AI model. “AI management brief” demonstrates the planned AI workflow. No API key, external data transfer or autonomous regulatory interpretation.')+(generated?`<div class="brief-paper"><div class="brief-top"><div><div class="eyebrow">NORTHSTAR FINANCE / FICTIONAL</div><h2>${esc(generated.title)}</h2><p class="muted">Snapshot ${generated.asOf} · ${esc(generated.method)}</p></div><span class="pill ${briefApproval?'':'Medium'}">${briefApproval?'Reviewed — demo only':'DRAFT · NOT APPROVED'}</span></div>${generated.sections.map(s=>`<section class="brief-section"><h3>${s.title}</h3><p>${esc(s.text)}</p><span class="source">Evidence references: ${esc(s.sources)}</span></section>`).join('')}<div class="notice">${disclaimer} This is an October snapshot briefing, not a complete monthly regulatory assessment.</div>${briefApproval?`<div class="audit"><strong>Human review recorded · ${esc(briefApproval.reviewer)}</strong><p>${esc(briefApproval.note)}</p><small>${briefApproval.time} · Session-only, identity not verified</small></div>`:reviewForm('brief','I have checked the source registers, sample limitations and management commentary.','Record briefing review')}<p class="safety">Any subsequent data or review change invalidates this briefing and its approval. Rebuild from the updated registers.</p></div>`:panel('Ready for human review, never auto-published','A briefing with evidence references, uncertainty and explicit decision requests.',`<div class="panel-body"><div class="flow">${[['01','Calculate','Use the same metric functions that power the dashboard.'],['02','Explain','Generate risk, outcome and overdue-action commentary from structured data.'],['03','Challenge & approve','A human validates evidence, scope and wording before governance use.']].map(([n,t,s])=>`<div class="node"><b>${n}</b><strong>${t}</strong><small>${s}</small></div>`).join('')}</div><p class="safety">Future LLM integration: server-side structured metrics → constrained summarisation → numeric validation → reviewer. See architecture notes in the README.</p></div>`))}
function about(){return heading('Gurjit Kaila / portfolio project','Built from operational understanding.','Financial Services Compliance Oversight & AI Governance — Portfolio Prototype.',`<a class="primary" style="padding:10px 15px;border-radius:5px" href="https://github.com/gurj86/ai-compliance-control-room" target="_blank" rel="noreferrer">View source on GitHub ↗</a>`)+`<div class="panel section"><div class="panel-body prose"><div class="eyebrow">REQUIREMENTS → CONTROLS → EVIDENCE → DECISIONS</div><h2 class="landing-title">AI Compliance Oversight & SMF16 Governance Command Centre</h2><p>This prototype demonstrates how a financial-services subject-matter expert can turn operational and governance needs into requirements, control testing, management information, escalation paths and controlled AI-enabled workflows.</p><p>Gurjit Kaila brings practical experience across remediation, Consumer Duty, complaints, outcome testing, pensions, investments and regulated customer journeys. The project uses that operational perspective to explore what a senior compliance function would need to see, challenge and evidence.</p><div class="notice">Gurjit does not claim to have held SMF16 status, Head of Compliance accountability or formal second-line leadership responsibility. Privacy and financial-crime modules demonstrate workflow design and oversight exposure; they do not claim direct specialist operational experience.</div><h2>Designed around a real role's workflow needs</h2><p>The supplied UpCredit Senior Compliance Lead advert informed the module blueprint: monitoring, advisory-style impact assessment, customer outcomes, privacy oversight, governance and regulatory change. Northstar Finance is entirely fictional. This project is not affiliated with or endorsed by UpCredit.</p><h2>What a recruiter can explore</h2><ol><li>Open the risk map and trace a customer support risk through its business area, control, monitoring review and finding.</li><li>Inspect F04's submitted evidence. Record independent review with a rationale; watch the queue and metrics recalculate.</li><li>Prepare the SMF16 monthly briefing and inspect its source references before recording human review.</li></ol></div></div>${panel('Architecture / governed insight','V1 is a static, synthetic prototype. Dashed future integration is documented in README.',`<div class="panel-body"><div class="flow">${[['01','Business inputs','Complaints, QA, monitoring, customer journeys — synthetic data.json only.'],['02','Governed data layer','Linked IDs, dated records, ownership, status and validation checks.'],['03','Control & analytics engine','Deterministic calculations, action queue and evidence gates.'],['04','Insight layer','V1 deterministic briefing. Future: constrained server-side LLM.'],['05','Human compliance review','Validate findings, interpretations, closures and management outputs.'],['06','Governance forums','Illustrative committee / board MI and decision evidence. No automatic distribution.']].map(([n,t,s])=>`<div class="node"><b>${n}</b><strong>${t}</strong><small>${s}</small></div>`).join('')}</div></div>`)}<div class="section"></div><div class="grid">${panel('BA & compliance transformation capability','A portfolio of requirements thinking.',`<div class="panel-body prose"><ul><li>Translate operational and regulatory oversight needs into controls, information requirements and accountable workflows.</li><li>Design exception escalation and evidence-led closure with explicit human approval points.</li><li>Separate calculated source metrics from AI-assisted interpretation and management commentary.</li></ul></div>`)}${panel('Recruiter explanation','A clear, accurate project narrative.',`<div class="panel-body prose"><p>“I used my regulated financial-services experience to build a working prototype of compliance oversight. It shows how I translate operational problems into linked controls, monitoring, MI and human-reviewed management briefings. It demonstrates BA and compliance-transformation capability; it is not a claim that I have held an SMF16 role.”</p><a href="README.md" class="help-link">Read project notes & CV bullets ↗</a> · <a href="data.json" download class="help-link">Download fictional dataset ↓</a></div>`)}</div>${notice()}`}
function reviewForm(id,check='I have reviewed the evidence, scope and limitations; this is a demo decision only.',label='Record human review'){return `<form class="review-form" data-form="${id}"><label>Reviewer name / role (demo, identity not verified)<input name="reviewer" required maxlength="100" placeholder="e.g. Demo independent reviewer"></label><label>Decision rationale / limitations (at least 20 characters)<textarea name="note" required minlength="20" maxlength="2000" placeholder="Explain what was checked, any limitations and the decision…"></textarea></label><label class="check-label"><input name="checked" type="checkbox" required>${check}</label><button class="primary" type="submit">${label}</button></form>`}
function openDialog(html){$('#dialog-content').innerHTML=html;$('#detail').showModal()}
function riskDetail(id){const r=d.risks.find(r=>r.id===id),cs=d.controls.filter(c=>c.riskId===id),fs=d.findings.filter(f=>cs.some(c=>c.id===f.controlId));openDialog(`<div class="eyebrow">LINKED RISK / CONTROL / EVIDENCE</div><h2>${r.id} · ${esc(r.name)}</h2><div class="detail-grid"><div><small>Business area</small>${esc(r.area)}</div><div><small>Accountable owner</small>${esc(r.owner)}</div><div><small>Illustrative residual score</small>${r.likelihood} likelihood × ${r.impact} impact = ${score(r)}/25</div><div><small>Previous snapshot</small>${r.previousScore}/25</div></div><div class="network"><div class="node"><strong>${esc(r.theme)}</strong><small>Risk theme · ${r.id}</small></div><span class="arrow">→</span><div class="node"><strong>${esc(r.area)}</strong><small>Business area</small></div><span class="arrow">→</span><div class="node">${cs.map(c=>`<strong>${c.id}</strong> ${esc(c.name)}<small>${c.tested} tested / ${c.failed} exceptions</small>`).join('')}</div><span class="arrow">→</span><div class="node">${fs.map(f=>`<button data-detail="${f.id}">${f.id} · ${f.status} ↗</button>`).join('<br>')}</div></div><h3>Linked findings</h3>${table(['Finding','Severity / status','Evidence'],fs.map(f=>[`${f.id} · ${esc(f.title)}`,`${badge(f.severity)} ${badge(f.status)}`,`${f.evidence.length} item(s) ${reviewButton(f)}`]))}<p class="safety">Select a linked finding to inspect its action, ownership and evidence trail. Scores are illustrative judgement inputs, not automated regulatory conclusions.</p>`)}
function monitorDetail(id){const m=d.monitoring.find(m=>m.id===id),c=d.controls.find(c=>c.id===m.controlId),fs=d.findings.filter(f=>f.controlId===c.id);openDialog(`<div class="eyebrow">MONITORING SCOPE</div><h2>${m.id} · ${esc(m.name)}</h2><div class="detail-grid"><div><small>Window</small>${m.start} → ${m.end}</div><div><small>Reviewer</small>${esc(m.owner)}</div><div><small>Status</small>${m.status}</div><div><small>Linked control</small>${c.id} · ${esc(c.name)}</div></div><p>Scope: sample customer journeys and review evidence of control operation. Testing and retest assumptions are fictional. Planned reviews have not generated test results.</p><h3>Related findings</h3>${fs.map(f=>`<div class="audit">${f.id} · ${esc(f.title)} ${reviewButton(f)}</div>`).join('')}<button data-risk="${c.riskId}">Explore risk relationship ↗</button>`)}
function detail(id){$('#detail').close();const f=d.findings.find(x=>x.id===id);if(f){const c=d.controls.find(c=>c.id===f.controlId);openDialog(`<div class="eyebrow">FINDING / CONTROL ${f.controlId} / RISK ${c.riskId}</div><h2>${f.id} · ${esc(f.title)}</h2><div class="detail-grid"><div><small>Status / severity</small>${badge(f.status)} ${badge(f.severity)}</div><div><small>Owner / due date</small>${esc(f.owner)}<br>${due(f)}</div></div><h3>Root cause</h3><p>${esc(f.rootCause)}</p><h3>Required action</h3><p>${esc(f.action)}</p><h3>Evidence & closure basis</h3>${f.evidence.length?f.evidence.map(e=>`<div class="audit"><strong>${e.id} · ${esc(e.title)}</strong><p>${esc(e.detail)}</p><small>Submitted by ${esc(e.submittedBy)} · ${e.date} · FICTIONAL</small></div>`).join(''):'<p class="muted">No closure evidence submitted. Closure is blocked.</p>'}${f.status==='Closed'?`<div class="audit">Closed ${f.closedAt} by ${esc(f.approvedBy)}. Fictional independent review; see evidence scope above.</div>`:!f.reviewed?reviewForm(`validate:${id}`,'I have validated the material finding and its proposed escalation; this does not approve closure.','Validate material finding'):''}${f.status==='Open'?`<form class="review-form" data-form="evidence:${id}"><h3>Submit demo closure evidence</h3><label>Evidence title<input name="title" required maxlength="140"></label><label>Retest results, scope and limitations<textarea name="note" required minlength="30" maxlength="2000"></textarea></label><button type="submit">Submit evidence for independent review</button></form>`:''}${f.status==='Evidence submitted'?reviewForm(`close:${id}`,'I have independently reviewed retest scope and closure evidence. For F04, submission alone does not prove closure; record whether additional assessment has been completed.','Approve closure — demo'):''}<p class="safety">All actions are session-only workflow simulations. Reviewer identities and independence are not authenticated. Closure needs evidence, human validation and a reviewer different from the action owner.</p>`);return;}
const x=[...d.changes,...d.privacy,...d.fincrime,...d.attestations,...d.issues].find(x=>x.id===id);if(!x)return;const isReg=id.startsWith('RC'),isAt=id.startsWith('AT');openDialog(`<div class="eyebrow">FICTIONAL OVERSIGHT RECORD / ${id}</div><h2>${esc(x.title)}</h2><div class="detail-grid"><div><small>Owner</small>${esc(x.owner)}</div><div><small>Internal target</small>${due(x)}</div><div><small>Type / status</small>${esc(x.type||x.classification||'Governance review')}<br>${badge(x.status)}</div><div><small>Linked risk / source</small>${esc(x.riskId||'Governance')}${x.source?'<br>'+esc(x.source):''}</div></div>${x.impact?`<h3>Impact assessment</h3><p>${esc(x.products)} · ${esc(x.impact)}</p>`:''}<h3>Risk / required action / evidence</h3><p>${esc(x.risk||'')} ${esc(x.action||x.evidence)}</p>${isReg?notice('This regulatory scenario is invented. A demo review records workflow progression, not a valid legal interpretation or implementation sign-off.'):''}${x.status==='Attested'||x.approved?'<div class="audit">Demo human review already recorded. See governance decision trail.</div>':reviewForm(`${isReg?'interpret':isAt?'attest':'specialist'}:${id}`,isAt?'I have reviewed the stated evidence scope and limitations for this demo attestation.':'I have reviewed this fictional assessment and recorded rationale; no regulatory or specialist conclusion is automated.',isReg?'Record interpretation review':isAt?'Record attestation':'Record specialist review')}<p class="safety">Session-only demonstration. This does not close a legal obligation or remove unresolved specialist actions.</p>`)}
function render(){view=location.hash.slice(1)||'overview';if(!nav.some(n=>n[0]===view))view='overview';$('#navigation').innerHTML=nav.map(([id,icon,name])=>`<a href="#${id}" ${view===id?'class="active" aria-current="page"':''}><span class="icon" aria-hidden="true">${icon}</span>${name}</a>`).join('');$('#crumb').textContent=nav.find(n=>n[0]===view)[2];$('#main').innerHTML=({overview,monitoring,outcomes,regulatory,governance,privacy:()=>specialist('privacy'),fincrime:()=>specialist('fincrime'),brief:briefing,about})[view]();if(view==='monitoring')renderFindings();if(view==='governance')renderQueue();}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('.dialog-close')){$('#detail').close();return;}if(b.dataset.detail){detail(b.dataset.detail);return;}if(b.dataset.risk){$('#detail').close();riskDetail(b.dataset.risk);return;}if(b.dataset.monitor){monitorDetail(b.dataset.monitor);return;}if(b.hasAttribute('data-prepare')){generated=brief(d);briefApproval=null;if(view!=='brief')location.hash='brief';else render();toast('Draft generated from calculated metrics. Human review required.');return;}if(b.id==='reset'){d=structuredClone(seed);audit=[];generated=null;briefApproval=null;$('#detail').close();render();toast('Synthetic snapshot restored. Session decisions cleared.');}if(b.id==='export-audit')download('demo-decision-trail.json',JSON.stringify({classification:'FICTIONAL; session-only; identities unverified',snapshot:d.meta.asOf,audit},null,2),'application/json');if(b.id==='download-brief'){download('compliance-briefing-demo.md',`# ${generated.title}\n\nFICTIONAL PORTFOLIO PROTOTYPE | Snapshot: ${generated.asOf}\n\n${briefApproval?'Reviewed (demo only) by '+briefApproval.reviewer+' — '+briefApproval.note:'DRAFT — NOT APPROVED'}\n\n${generated.method}\n\n${generated.sections.map(s=>`## ${s.title}\n${s.text}\n\nEvidence: ${s.sources}`).join('\n\n')}\n\n${disclaimer}`);}if(b.id==='print-brief')window.print();});
document.addEventListener('input',e=>{if(e.target.id==='finding-search')renderFindings()});
document.addEventListener('change',e=>{if(e.target.id==='monitor-mode')renderFindings();if(e.target.id==='queue-filter'){queueFilter=e.target.value;renderQueue()}if(e.target.id==='calendar-month'){calendarMonth=e.target.value;$('#calendar').innerHTML=timeline()}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('[data-form]'))return;e.preventDefault();const fd=new FormData(form),[kind,id]=form.dataset.form.split(':'),reviewer=String(fd.get('reviewer')||'').trim(),note=String(fd.get('note')||'').trim();try{if(kind!=='evidence'&&(!reviewer||note.length<20||!fd.get('checked')))throw Error('Reviewer, rationale and confirmation are required.');if(kind==='brief'){briefApproval={reviewer,note,time:new Date().toISOString()};audit.unshift({type:'Briefing review',id:'BRIEF',reviewer,note,time:briefApproval.time});render();toast('Briefing review recorded for this session.');return;}if(kind==='close'){closeFinding(d,id,reviewer,note);log('Closure approved',id,reviewer,note);}if(kind==='validate'){d.findings.find(f=>f.id===id).reviewed=true;log('Material finding validated',id,reviewer,note);}if(kind==='evidence'){if(note.length<30)throw Error('Include retest scope and limitations (30 characters minimum).');const f=d.findings.find(f=>f.id===id);f.evidence.push({id:`E-${id}-${f.evidence.length+1}`,title:String(fd.get('title')).trim(),detail:note,submittedBy:f.owner,date:d.meta.asOf});f.status='Evidence submitted';log('Evidence submitted',id,f.owner,note);}if(kind==='interpret'){const x=d.changes.find(x=>x.id===id);x.status='Implementation planning';x.approved=true;log('Demo interpretation reviewed',id,reviewer,note);}if(kind==='attest'){d.attestations.find(x=>x.id===id).status='Attested';log('Attestation recorded',id,reviewer,note);}if(kind==='specialist'){log('Specialist review recorded',id,reviewer,note);}$('#detail').close();render();toast('Demo decision recorded. Metrics and queues refreshed; prior briefing invalidated.');}catch(err){toast(err.message)}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
